import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.E8pQZ6KS.js";const u=JSON.parse('{"title":"计算机网络","description":"","frontmatter":{},"headers":[],"relativePath":"专业基础/计算机网络.md","filePath":"专业基础/计算机网络.md","lastUpdated":1792430298000}'),d={name:"专业基础/计算机网络.md"};function i(o,t,h,s,n,_){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="计算机网络" tabindex="-1">计算机网络 <a class="header-anchor" href="#计算机网络" aria-label="Permalink to &quot;计算机网络&quot;">​</a></h1><blockquote><p>一切攻击都发生在网络上。校内课程（计算机网络原理 / 网络安全原理）是攻防方向的必修地基，抓包能力见 <a href="./../必学工具/抓包与流量分析.html">抓包与流量分析</a>。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>网络攻防、协议分析、Web 安全全部建立在网络协议之上；</li><li>理解 TCP/IP 才能看懂扫描、嗅探、中间人、DDoS 等攻击手法的原理；</li><li>校内「网络安全原理」（第 4 学期）直接承接本课程。</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>分层模型（应用 / 传输 / 网络 / 链路）</li><li>TCP / UDP 详解（三次握手、四次挥手、可靠传输）</li><li>IP 编址与路由</li><li>DNS、HTTP/HTTPS、DHCP、ARP 等关键协议</li><li>网络安全基础（加密的传输层实现、防火墙概念）</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《计算机网络：自顶向下方法》（Kurose &amp; Ross）</td><td>书</td><td>国际经典教材，配合 Wireshark 实验</td></tr><tr><td>哈工大《计算机网络》</td><td>中国大学 MOOC</td><td>中文口碑课程（以平台实际为准）</td></tr><tr><td>Stanford CS144</td><td>公开课</td><td>动手实现 TCP 的硬核课程</td></tr><tr><td><a href="https://www.wireshark.org/docs/wsug_html_chunked/" target="_blank" rel="noreferrer">Wireshark 实验指南</a></td><td>文档</td><td>官方用户手册</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li><strong>每学一个协议，就用 Wireshark 抓一次真实流量</strong>——把理论和报文对上号；</li><li>重点吃透 TCP 状态机与 HTTP 报文结构（Web 安全绕不开）；</li><li>大二配齐网络基础后，再进入 <a href="./../安全方向/网络攻防.html">网络攻防</a> 方向会非常顺畅。</li></ul>',10)])])}const P=a(d,[["render",i]]);export{u as __pageData,P as default};
